/**
 * Manual SQL lexer (character scanner, no regular expressions).
 *
 * Produces a flat token stream just rich enough to drive the statement
 * splitter. Token types:
 *   'ws'      - whitespace run excluding newlines (space, tab, vtab, formfeed)
 *   'nl'      - newline run (\n, \r)
 *   'comment' - line comment (-- or #, up to but excluding the newline)
 *               or block comment (/* ... *\/, only when terminated)
 *   'string'  - quoted string/identifier ('', "", `` or $tag$...$tag$),
 *               only when a valid closing delimiter exists
 *   'word'    - run of [A-Za-z0-9_]
 *   'punct'   - one of ( ) ;
 *   'other'   - any other single character
 *
 * Every token is { type, value } where value is the exact source slice.
 */

const CH_TAB = 9;
const CH_LF = 10;
const CH_VT = 11;
const CH_FF = 12;
const CH_CR = 13;
const CH_SPACE = 32;
const CH_HASH = 35;        // #
const CH_DOLLAR = 36;      // $
const CH_SQUOTE = 39;      // '
const CH_LPAREN = 40;      // (
const CH_RPAREN = 41;      // )
const CH_SEMI = 59;        // ;
const CH_DQUOTE = 34;      // "
const CH_BACKTICK = 96;    // `
const CH_SLASH = 47;       // /
const CH_STAR = 42;        // *
const CH_MINUS = 45;       // -
const CH_BACKSLASH = 92;   // \
const CH_UNDERSCORE = 95;  // _

function isDigit(code) {
  return code >= 48 && code <= 57;
}

function isAlpha(code) {
  return (code >= 65 && code <= 90) || (code >= 97 && code <= 122);
}

function isWordChar(code) {
  return isAlpha(code) || isDigit(code) || code === CH_UNDERSCORE;
}

function isSpaceNoNewline(code) {
  return code === CH_SPACE || code === CH_TAB ||
         code === CH_VT || code === CH_FF;
}

function isNewline(code) {
  return code === CH_LF || code === CH_CR;
}

function isQuoteChar(code) {
  return code === CH_SQUOTE || code === CH_DQUOTE || code === CH_BACKTICK;
}

/** Scan a quoted string starting at index i (s[i] is the quote char).
 *  Returns the end index (exclusive) or -1 when unterminated.
 *  Inside a string, a backslash escapes the next character and a doubled
 *  quote acts as an escaped quote. */
function scanQuoted(sql, i) {
  const quote = sql.charCodeAt(i);
  let j = i + 1;
  const n = sql.length;
  while (j < n) {
    const c = sql.charCodeAt(j);
    if (c === CH_BACKSLASH) {
      j += 2;
      continue;
    }
    if (c === quote) {
      if (j + 1 < n && sql.charCodeAt(j + 1) === quote) {
        j += 2; // doubled quote = escaped quote
        continue;
      }
      return j + 1;
    }
    j += 1;
  }
  return -1;
}

/** Find needle in sql starting at from. Manual substring search. */
function indexOfFrom(sql, needle, from) {
  const n = sql.length;
  const m = needle.length;
  if (m === 0) return from;
  const first = needle.charCodeAt(0);
  for (let i = from; i + m <= n; i++) {
    if (sql.charCodeAt(i) !== first) continue;
    let ok = true;
    for (let k = 1; k < m; k++) {
      if (sql.charCodeAt(i + k) !== needle.charCodeAt(k)) {
        ok = false;
        break;
      }
    }
    if (ok) return i;
  }
  return -1;
}

/** Scan a dollar-quoted string starting at index i (s[i] === '$').
 *  Returns the end index (exclusive) or -1 when it is not a complete
 *  dollar-quoted string. */
function scanDollarQuoted(sql, i) {
  const n = sql.length;
  let j = i + 1;
  while (j < n && isWordChar(sql.charCodeAt(j))) {
    j += 1;
  }
  if (j >= n || sql.charCodeAt(j) !== CH_DOLLAR) {
    return -1; // not a $tag$ opener
  }
  const tag = sql.slice(i + 1, j);
  const closing = '$' + tag + '$';
  const closeStart = indexOfFrom(sql, closing, j + 1);
  if (closeStart === -1) {
    return -1;
  }
  return closeStart + closing.length;
}

/** Tokenize the whole SQL string into { type, value } tokens. */
export function tokenize(sql) {
  const tokens = [];
  const n = sql.length;
  let i = 0;
  while (i < n) {
    const c = sql.charCodeAt(i);

    if (isSpaceNoNewline(c)) {
      let j = i + 1;
      while (j < n && isSpaceNoNewline(sql.charCodeAt(j))) j += 1;
      tokens.push({ type: 'ws', value: sql.slice(i, j) });
      i = j;
      continue;
    }

    if (isNewline(c)) {
      let j = i + 1;
      while (j < n && isNewline(sql.charCodeAt(j))) j += 1;
      tokens.push({ type: 'nl', value: sql.slice(i, j) });
      i = j;
      continue;
    }

    // Line comments: -- ... or # ... up to (not including) the newline.
    if ((c === CH_MINUS && i + 1 < n && sql.charCodeAt(i + 1) === CH_MINUS) ||
        c === CH_HASH) {
      let j = i;
      while (j < n && !isNewline(sql.charCodeAt(j))) j += 1;
      tokens.push({ type: 'comment', value: sql.slice(i, j) });
      i = j;
      continue;
    }

    // Block comment: only when a closing */ exists.
    if (c === CH_SLASH && i + 1 < n && sql.charCodeAt(i + 1) === CH_STAR) {
      const close = indexOfFrom(sql, '*/', i + 2);
      if (close !== -1) {
        tokens.push({ type: 'comment', value: sql.slice(i, close + 2) });
        i = close + 2;
        continue;
      }
      // Unterminated: the '/' is an ordinary character.
    }

    // Quoted strings / identifiers: only when properly terminated.
    if (isQuoteChar(c)) {
      const end = scanQuoted(sql, i);
      if (end !== -1) {
        tokens.push({ type: 'string', value: sql.slice(i, end) });
        i = end;
        continue;
      }
      // Unterminated: the quote is an ordinary character.
    }

    // Dollar-quoted strings: only when properly terminated.
    if (c === CH_DOLLAR) {
      const end = scanDollarQuoted(sql, i);
      if (end !== -1) {
        tokens.push({ type: 'string', value: sql.slice(i, end) });
        i = end;
        continue;
      }
    }

    if (isWordChar(c)) {
      let j = i + 1;
      while (j < n && isWordChar(sql.charCodeAt(j))) j += 1;
      tokens.push({ type: 'word', value: sql.slice(i, j) });
      i = j;
      continue;
    }

    if (c === CH_LPAREN || c === CH_RPAREN || c === CH_SEMI) {
      tokens.push({ type: 'punct', value: sql.slice(i, i + 1) });
      i += 1;
      continue;
    }

    tokens.push({ type: 'other', value: sql.slice(i, i + 1) });
    i += 1;
  }
  return tokens;
}

/**
 * Statement splitter: splits a SQL string into individual statements,
 * reproducing the observable behavior of Python's sqlparse.split().
 *
 * Split level bookkeeping (derived black-box from the reference behavior):
 *   '('                -> level + 1
 *   ')'                -> level - 1
 *   keyword CREATE     -> marks the statement as a CREATE statement
 *   keyword DECLARE    -> level + 1 (only in a CREATE stmt at BEGIN depth 0)
 *   keyword BEGIN      -> BEGIN depth + 1, level + 1
 *   keyword IF/FOR/WHILE -> level + 1 (only in a CREATE stmt, BEGIN depth > 0)
 *   keyword END        -> BEGIN depth - 1 (if > 0), level - 1
 * The level never drops below 0.
 * A ';' at level 0 terminates the current statement. Whitespace (not
 * newlines) and comments immediately following it stay attached to the
 * terminated statement; the next other token starts a new statement.
 *
 * Each emitted chunk is stripped (Python str.strip semantics) and empty
 * chunks are dropped.
 */

import { tokenize } from './lexer.mjs';

/** ASCII-only uppercase, sufficient for SQL keywords. */
function upperAscii(text) {
  let out = '';
  for (let i = 0; i < text.length; i++) {
    const c = text.charCodeAt(i);
    out += (c >= 97 && c <= 122) ? String.fromCharCode(c - 32) : text[i];
  }
  return out;
}

/** Python str.isspace-style whitespace test for a single character. */
function isPySpace(code) {
  if (code <= 32) return true;             // includes \t\n\v\f\r and 0x1c-0x1f
  if (code === 133 || code === 160) return true;
  if (code === 5760) return true;          // OGHAM SPACE MARK
  if (code >= 8192 && code <= 8202) return true;
  if (code === 8232 || code === 8233) return true;
  if (code === 8239 || code === 8287 || code === 12288) return true;
  return false;
}

/** Python str.strip() equivalent. */
export function pyStrip(text) {
  let start = 0;
  let end = text.length;
  while (start < end && isPySpace(text.charCodeAt(start))) start += 1;
  while (end > start && isPySpace(text.charCodeAt(end - 1))) end -= 1;
  return text.slice(start, end);
}

/** Split a SQL string into statements. */
export function split(sql) {
  const tokens = tokenize(sql);

  const chunks = [];
  let buf = [];
  let level = 0;
  let beginDepth = 0;
  let isCreate = false;
  let consumeWs = false;

  const reset = () => {
    buf = [];
    level = 0;
    beginDepth = 0;
    isCreate = false;
    consumeWs = false;
  };

  for (const token of tokens) {
    const isEos = token.type === 'ws' || token.type === 'comment';

    if (consumeWs && !isEos) {
      // A new statement begins: emit what we collected.
      chunks.push(buf.join(''));
      reset();
    }

    if (isEos && !isCreate) {
      buf.push(token.value);
      continue;
    }

    let delta = 0;
    if (token.type === 'punct') {
      if (token.value === '(') delta = 1;
      else if (token.value === ')') delta = -1;
    } else if (token.type === 'word') {
      const word = upperAscii(token.value);
      if (word === 'CREATE') {
        isCreate = true;
      } else if (word === 'DECLARE') {
        if (isCreate && beginDepth === 0) delta = 1;
      } else if (word === 'BEGIN') {
        beginDepth += 1;
        delta = 1;
      } else if (word === 'IF' || word === 'FOR' || word === 'WHILE') {
        if (isCreate && beginDepth > 0) delta = 1;
      } else if (word === 'END') {
        if (beginDepth > 0) beginDepth -= 1;
        delta = -1;
      }
    }

    level += delta;
    if (level < 0) level = 0;

    if (level === 0 && token.type === 'punct' && token.value === ';') {
      consumeWs = true;
    }

    buf.push(token.value);
  }

  if (buf.length > 0) {
    chunks.push(buf.join(''));
  }

  const result = [];
  for (const chunk of chunks) {
    const stripped = pyStrip(chunk);
    if (stripped.length > 0) {
      result.push(stripped);
    }
  }
  return result;
}

/**
 * Python-compatible formatting helpers: reproduce repr() of str and of a
 * list of str so console output matches Python's print() byte for byte.
 */

function hex2(code) {
  const h = code.toString(16);
  return h.length === 1 ? '0' + h : h;
}

function hex4(code) {
  let h = code.toString(16);
  while (h.length < 4) h = '0' + h;
  return h;
}

/** Non-printable code points that Python's repr() escapes as \xhh / \uxxxx. */
function isNonPrintable(code) {
  if (code < 32 || (code >= 127 && code <= 160)) return true;
  if (code === 173) return true;                    // SOFT HYPHEN (Cf)
  if (code >= 8192 && code <= 8207) return true;    // Zs/Cf space & format chars
  if (code === 8232 || code === 8233) return true;  // Zl / Zp
  if (code === 8239 || code === 8287) return true;  // narrow / medium spaces
  if (code === 65279) return true;                  // ZERO WIDTH NO-BREAK SPACE
  return false;
}

/** repr() of a Python str. */
export function reprStr(text) {
  const hasSingle = text.indexOf("'") !== -1;
  const hasDouble = text.indexOf('"') !== -1;
  const quote = (hasSingle && !hasDouble) ? '"' : "'";

  let out = quote;
  for (const ch of text) { // iterates by code point
    const code = ch.codePointAt(0);
    if (ch === quote || ch === '\\') {
      out += '\\' + ch;
    } else if (ch === '\n') {
      out += '\\n';
    } else if (ch === '\r') {
      out += '\\r';
    } else if (ch === '\t') {
      out += '\\t';
    } else if (isNonPrintable(code)) {
      out += (code <= 255) ? '\\x' + hex2(code) : '\\u' + hex4(code);
    } else {
      out += ch;
    }
  }
  out += quote;
  return out;
}

/** repr() of a Python list of str. */
export function reprList(items) {
  let out = '[';
  for (let i = 0; i < items.length; i++) {
    if (i > 0) out += ', ';
    out += reprStr(items[i]);
  }
  out += ']';
  return out;
}

/**
 * Minimal emulation of the Python argparse configuration used by the
 * original script:
 *
 *   parser = argparse.ArgumentParser()
 *   parser.add_argument('--a', type=str, required=True)
 *
 * Supports: --a VALUE, --a=VALUE, unambiguous long-option prefixes,
 * -h/--help, '--' end-of-options marker, last-occurrence-wins for repeated
 * options, and argparse's exact error/usage messages with exit code 2.
 */

const LONG_OPTIONS = ['help', 'a'];

function usageLine(prog) {
  return 'usage: ' + prog + ' [-h] --a A';
}

function printHelp(prog) {
  let out = usageLine(prog) + '\n\n';
  out += 'options:\n';
  out += '  -h, --help  show this help message and exit\n';
  out += '  --a A\n';
  process.stdout.write(out);
  process.exit(0);
}

function fail(prog, message) {
  process.stderr.write(usageLine(prog) + '\n');
  process.stderr.write(prog + ': error: ' + message + '\n');
  process.exit(2);
}

/** Would argparse treat this token as an option string rather than a value? */
function looksLikeOption(token) {
  if (token.length < 2 || token[0] !== '-') return false;
  const second = token.charCodeAt(1);
  if (second >= 48 && second <= 57) return false; // negative number -> value
  return true;
}

/** Parse argv (already sliced past `node script`). Returns { a }. */
export function parseArgs(argv, prog) {
  let a;
  const extras = [];
  let seenDashDash = false;

  let i = 0;
  while (i < argv.length) {
    const token = argv[i];

    if (seenDashDash) {
      extras.push(token);
      i += 1;
      continue;
    }

    if (token === '--') {
      seenDashDash = true;
      i += 1;
      continue;
    }

    if (token === '-h') {
      printHelp(prog);
    }

    if (token.length > 2 && token[0] === '-' && token[1] === '-') {
      const body = token.slice(2);
      const eq = body.indexOf('=');
      const name = eq === -1 ? body : body.slice(0, eq);
      const inlineValue = eq === -1 ? undefined : body.slice(eq + 1);

      // Exact or unambiguous-prefix match against the long options.
      let matches = LONG_OPTIONS.filter((o) => o === name);
      if (matches.length === 0) {
        matches = LONG_OPTIONS.filter((o) => o.startsWith(name));
      }

      if (matches.length === 0) {
        extras.push(token);
        i += 1;
        continue;
      }
      if (matches.length > 1) {
        const pretty = matches.map((o) => '--' + o).join(', ');
        fail(prog, 'ambiguous option: --' + name + ' could match ' + pretty);
      }

      const option = matches[0];
      if (option === 'help') {
        printHelp(prog);
      }

      // option === 'a'
      if (inlineValue !== undefined) {
        a = inlineValue;
      } else {
        const next = argv[i + 1];
        if (next === undefined || looksLikeOption(next)) {
          fail(prog, 'argument --a: expected one argument');
        }
        a = next;
        i += 1;
      }
      i += 1;
      continue;
    }

    // Unknown short option or positional argument.
    extras.push(token);
    i += 1;
  }

  if (a === undefined) {
    fail(prog, 'the following arguments are required: --a');
  }
  if (extras.length > 0) {
    fail(prog, 'unrecognized arguments: ' + extras.join(' '));
  }

  return { a };
}

/**
 * Entry point — Node.js (ESM) port of /workspace/dataset/sqlparse/test2.py.
 *
 *   parser = argparse.ArgumentParser()
 *   parser.add_argument('--a', type=str, required=True)
 *   result = sqlparse.split(args.a)
 *   print(result)
 */

import { parseArgs } from './lib/argparse.mjs';
import { split } from './lib/sql/splitter.mjs';
import { reprList } from './lib/pyformat.mjs';

/** basename of the invoked script, like argparse's prog default. */
function progName() {
  const script = process.argv[1] || 'test2.mjs';
  const slash = script.lastIndexOf('/');
  return slash === -1 ? script : script.slice(slash + 1);
}

function main() {
  const args = parseArgs(process.argv.slice(2), progName());
  const result = split(args.a); // split multiple SQL statements
  console.log(reprList(result));
}

main();

